"""Module 01 concepts: logic circuits and ICs (EASA M04 SM01; Jaeger Ch.6-7, 9 digital parts)."""
from lib import K
M = 'm01'
K('m01-binary', M, ('Hệ nhị phân và đổi số', 'Binary numbers and conversion'),
  ('Hệ đếm cơ số 2 dùng hai chữ số 0 và 1; mỗi cột có giá trị 2ⁿ (1, 2, 4, 8, 16…). BCD mã hoá mỗi chữ số thập phân bằng 4 bit.', 'Base-2 counting uses the digits 0 and 1; each column is worth 2ⁿ (1, 2, 4, 8, 16…). BCD codes each decimal digit with 4 bits.'),
  facts=[('giá trị = Σ bᵢ·2ⁱ', ('Cộng các cột có bit 1.', 'Add the columns that hold a 1.')), ('n bit → 2ⁿ giá trị (0 … 2ⁿ − 1)', ('Ví dụ 8 bit: 0…255.', 'For 8 bits: 0…255.')),
         ('BCD: 0000 … 1001 cho 0 … 9', ('45₁₀ = 0100 0101 (BCD) nhưng 45₁₀ = 101101₂.', '45₁₀ = 0100 0101 (BCD) but 45₁₀ = 101101₂.'))],
  steps=[('Thập phân → nhị phân: chia 2 liên tiếp, ghi phần dư, đọc từ dưới lên (hoặc trừ dần 32, 16, 8…).', 'Decimal → binary: divide by 2 repeatedly and read the remainders from the bottom up (or subtract 32, 16, 8…).'),
         ('Nhị phân → thập phân: viết giá trị cột phía trên từng bit rồi cộng các cột có 1.', 'Binary → decimal: write the column values above the bits and add those holding 1.'),
         ('Cộng nhị phân: 0+0=0, 0+1=1, 1+1=10 (viết 0 nhớ 1).', 'Binary addition: 0+0=0, 0+1=1, 1+1=10 (write 0, carry 1).')],
  traps=[('Nhầm BCD với nhị phân thuần: BCD không dùng các mã 1010…1111.', 'Confusing BCD with plain binary: BCD never uses the codes 1010…1111.'), ('Đọc phần dư từ trên xuống thay vì từ dưới lên.', 'Reading the remainders top-down instead of bottom-up.')],
  angles=[('Đổi một số thập phân (vd 45) sang nhị phân hoặc ngược lại.', 'Convert a decimal number (e.g. 45) to binary or back.'), ('Cộng hai số nhị phân và kiểm bằng thập phân.', 'Add two binary numbers and check in decimal.')],
  topics=['Binary numbers and conversion'], kw=['binary', 'bcd', 'convert', 'decimal', 'bit', 'base 2', 'column', 'remainder'], kwv=['nhị phân', 'thập phân', 'đổi số', 'bcd', 'chuyển đổi', 'số bit'],
  src=['EASA M04 SM01 (binary)'], related=['m01-adders', 'm01-gates'], chk='binary')
K('m01-gates', M, ('Cổng logic và bảng chân lý', 'Logic gates and truth tables'),
  ('Cổng logic là mạch có ngõ ra 0/1 là một hàm cố định của các ngõ vào; bảng chân lý liệt kê mọi tổ hợp. NAND và NOR là cổng vạn năng.', 'A logic gate has a 0/1 output that is a fixed function of its inputs; the truth table lists every combination. NAND and NOR are universal gates.'),
  facts=[('NAND = NOT(A·B) ,  NOR = NOT(A+B)', ('Đảo ngõ ra của AND/OR.', 'AND/OR with the output inverted.')), ('XOR = A·B̄ + Ā·B (ngõ ra 1 khi hai ngõ vào KHÁC nhau)', ('XOR khác OR chỉ ở trường hợp 1-1.', 'XOR differs from OR only for 1-1.')),
         ('De Morgan: NOT(A·B) = Ā + B̄ ,  NOT(A+B) = Ā·B̄', ('NOR ≡ AND-âm; NAND ≡ OR-âm.', 'NOR ≡ negative-AND; NAND ≡ negative-OR.'))],
  steps=[('Liệt kê 2ⁿ tổ hợp ngõ vào theo thứ tự nhị phân.', 'List the 2ⁿ input combinations in binary order.'), ('Tính từng cổng theo thứ tự tín hiệu đi qua rồi ghi cột ngõ ra.', 'Evaluate each gate in signal order and write the output column.'), ('Cổng nhiều ngõ vào: AND = 1 chỉ khi mọi ngõ vào 1; OR = 0 chỉ khi mọi ngõ vào 0.', 'Many inputs: AND = 1 only when all inputs are 1; OR = 0 only when all inputs are 0.')],
  traps=[('Nhầm XOR với OR ở tổ hợp 1-1.', 'Mixing up XOR and OR at the 1-1 case.'), ('Quên đảo khi đổi qua De Morgan: đổi cả dấu phép và đảo từng biến.', 'Forgetting to flip both the operator and each variable when applying De Morgan.')],
  angles=[('Cho sơ đồ cổng, tìm ngõ ra với ngõ vào cho trước.', 'Given a gate diagram, find the output for given inputs.'), ('Cổng nào cho ngõ ra 1 khi A = B = 1?', 'Which gate gives 1 when A = B = 1?')],
  topics=['Logic gates'], kw=['logic gate', 'and gate', 'or gate', 'not gate', 'nand', 'nor', 'xor', 'inverter', 'truth table', 'de morgan', 'logic level'], kwv=['cổng logic', 'bảng chân lý', 'cổng and', 'cổng or', 'cổng nand', 'cổng nor', 'cổng not', 'cổng đảo', 'de morgan'],
  src=['EASA M04 SM01 (logic gates)'], related=['m01-adders', 'm01-flipflops'], chk='gates')
K('m01-adders', M, ('Bộ cộng nửa và đầy đủ', 'Half-adder and full-adder'),
  ('Bộ cộng nửa cộng hai bit (tổng = XOR, nhớ = AND); bộ cộng đầy đủ cộng thêm bit nhớ vào, ghép chuỗi thành bộ cộng nhiều bit.', 'A half-adder adds two bits (sum = XOR, carry = AND); a full-adder also takes a carry in, and chaining them builds multi-bit adders.'),
  facts=[('Nửa: S = A ⊕ B ,  C = A·B', ('1 + 1 = 10₂: tổng 0, nhớ 1.', '1 + 1 = 10₂: sum 0, carry 1.')), ('Đầy đủ: S = A ⊕ B ⊕ Cin ,  Cout = A·B + Cin·(A ⊕ B)', ('Hai bộ nửa + một cổng OR.', 'Two half-adders + one OR gate.'))],
  steps=[('Cộng cột từ phải sang trái, mang bit nhớ sang cột trái.', 'Add column by column from the right, carrying left.'), ('Tổng của cột = XOR các bit vào (kể cả nhớ); nhớ ra = 1 khi có ít nhất hai bit vào bằng 1.', 'The column sum = XOR of the input bits (carry included); carry out = 1 when at least two input bits are 1.')],
  traps=[('Dùng bộ cộng nửa cho cột giữa: nó không nhận bit nhớ vào.', 'Using a half-adder for a middle column: it has no carry input.')],
  angles=[('Với A = B = 1, tổng và nhớ của bộ cộng nửa là gì?', 'For A = B = 1, what are the half-adder sum and carry?'), ('Cộng 101₂ + 011₂.', 'Add 101₂ + 011₂.')],
  topics=['Adders and combinational circuits'], kw=['adder', 'half adder', 'full adder', 'sum', 'carry', 'ripple'], kwv=['bộ cộng', 'cộng nửa', 'cộng đầy đủ', 'bit nhớ', 'số nhớ', 'tổng'],
  src=['EASA M04 SM01 (adders)'], related=['m01-gates', 'm01-binary'], chk='adders')
K('m01-combinational', M, ('Mạch tổ hợp: mã hoá, giải mã, so sánh', 'Combinational circuits: encoders, decoders, comparators'),
  ('Ngõ ra chỉ phụ thuộc ngõ vào hiện tại, không có nhớ. Giải mã n→2ⁿ đường, mã hoá 2ⁿ→n bit; mã hoá ưu tiên chọn ngõ vào cao nhất khi nhiều ngõ cùng cao.', 'The output depends only on the present inputs; there is no memory. A decoder goes n→2ⁿ lines, an encoder 2ⁿ→n bits; a priority encoder picks the highest input when several are HIGH.'),
  facts=[('giải mã n → 2ⁿ ngõ ra ;  mã hoá 2ⁿ → n', ('Giải mã 3→8: 8 ngõ ra.', '3→8 decoder: 8 outputs.')), ('enable = thấp → mọi ngõ ra thấp (giải mã kiểu EASA)', ('Chân enable chỉ kích hoạt, không làm phép logic.', 'The enable pin only activates; it performs no logic operation.'))],
  steps=[('Xác định số ngõ vào n để suy ra số ngõ ra.', 'Find the number of inputs n to get the number of outputs.'), ('Xét chân enable trước, rồi mới tới mã vào.', 'Check the enable pin first, then the input code.')],
  traps=[('Cho rằng chân enable thực hiện một phép logic.', 'Thinking the enable pin performs a logic operation.')],
  angles=[('Bộ giải mã có 4 ngõ vào có bao nhiêu ngõ ra?', 'How many outputs does a decoder with 4 inputs have?'), ('Khi enable thấp, trạng thái các ngõ ra?', 'With enable LOW, what are the outputs?')],
  topics=['Adders and combinational circuits'], kw=['encoder', 'decoder', 'priority encoder', 'comparator logic', 'enable', 'multiplexer', 'combinational'], kwv=['mã hoá', 'giải mã', 'mã hóa', 'enable', 'mạch tổ hợp', 'ưu tiên'],
  src=['EASA M04 SM01 (encoders, decoders)'], related=['m01-adders'], chk='comb')
K('m01-flipflops', M, ('Flip-flop và logic tuần tự', 'Flip-flops and sequential logic'),
  ('Flip-flop là mạch lưỡng ổn lưu một bit; ngõ ra kế tiếp phụ thuộc cả ngõ vào lẫn trạng thái hiện tại. Xung nhịp quyết định khi nào ngõ vào được chấp nhận.', 'A flip-flop is a bistable circuit that stores one bit; the next output depends on the inputs and on the present state. The clock decides when the inputs are accepted.'),
  facts=[('JK: Q⁺ = J·Q̄ + K̄·Q', ('J = K = 0 giữ; 0-1 xoá; 1-0 đặt; 1-1 đảo.', 'J = K = 0 hold; 0-1 reset; 1-0 set; 1-1 toggle.')), ('D: Q⁺ = D ;  T: Q⁺ = T ⊕ Q', ('D chép ngõ vào; T=1 đảo trạng thái.', 'D copies its input; T = 1 toggles.')), ('RS: S = R = 1 là tổ hợp cấm', ('JK khắc phục bằng chế độ đảo.', 'The JK fixes it by toggling.'))],
  steps=[('Đọc trạng thái hiện tại Q rồi tra ngõ vào ở cạnh xung nhịp.', 'Read the present state Q, then look up the inputs at the clock edge.'), ('Dùng Q⁺ = hàm(J, K, Q) để tính trạng thái kế tiếp, không đoán.', 'Use Q⁺ = f(J, K, Q) for the next state; do not guess.')],
  traps=[('Nhầm “đảo” (JK 1-1) với “cấm” (RS 1-1).', 'Confusing “toggle” (JK 1-1) with “forbidden” (RS 1-1).'), ('Cho rằng ngõ ra đổi ngay khi ngõ vào đổi, bỏ qua xung nhịp.', 'Assuming the output changes as soon as the input does, ignoring the clock.')],
  angles=[('J = K = 1 thì Q thay đổi thế nào qua mỗi xung?', 'With J = K = 1, how does Q change on each clock pulse?'), ('Tổ hợp ngõ vào nào bị cấm ở flip-flop RS?', 'Which input combination is forbidden in an RS flip-flop?')],
  topics=['Flip-flops and sequential logic'], kw=['flip-flop', 'flip flop', 'latch', 'jk', 'rs flip', 'clock pulse', 'toggle', 'set and reset', 'sequential', 'bistable', 'multivibrator'], kwv=['flip-flop', 'xung nhịp', 'lưỡng ổn', 'đảo trạng thái', 'đặt', 'xoá', 'tuần tự'],
  src=['EASA M04 SM01 (flip-flops)'], related=['m01-gates'], chk='flipflops')
K('m01-families', M, ('Họ logic TTL và CMOS, biên nhiễu', 'Logic families TTL and CMOS, noise margins'),
  ('TTL dùng transistor lưỡng cực, nguồn +5 V; CMOS dùng MOSFET bổ sung, nguồn rộng (EASA: +3 … +18 V), công suất tĩnh rất nhỏ nhưng nhạy ESD. Biên nhiễu cho biết mức nhiễu tối đa mà cổng còn chịu được.', 'TTL uses bipolar transistors on +5 V; CMOS uses complementary MOSFETs on a wide supply (EASA: +3 … +18 V), has very low static power but is ESD-sensitive. A noise margin is the largest noise a gate tolerates.'),
  facts=[('NMH = VOH − VIH ,  NML = VIL − VOL', ('Biên nhiễu mức cao và mức thấp (Jaeger Ch.6-7).', 'High and low noise margins (Jaeger Ch.6-7).')), ('CMOS: VOH = VDD ,  VOL = 0', ('Ngõ ra “đi hết” rail.', 'The output swings the full rail.'))],
  steps=[('Lấy VOH, VOL của cổng PHÁT và VIH, VIL của cổng NHẬN.', 'Take VOH, VOL from the driving gate and VIH, VIL from the receiving gate.'), ('Tính NMH và NML; biên nhiễu của cổng là giá trị nhỏ hơn.', 'Compute NMH and NML; the gate margin is the smaller one.')],
  traps=[('Lẫn VOH (ngõ ra) với VIH (ngõ vào) trong công thức.', 'Mixing up VOH (output) with VIH (input) in the formula.'), ('Quên CMOS nhạy tĩnh điện (xem module 09).', 'Forgetting that CMOS is static-sensitive (see module 09).')],
  angles=[('So sánh TTL và CMOS về nguồn và công suất.', 'Compare TTL and CMOS in supply and power.'), ('Tính biên nhiễu từ VOH, VOL, VIH, VIL.', 'Compute noise margins from VOH, VOL, VIH, VIL.')],
  topics=['ICs, TTL and CMOS'], kw=['ttl', 'cmos', 'noise margin', 'logic family', 'voh', 'vol', 'vih', 'vil', 'fan-out', 'supply voltage', 'bipolar'], kwv=['ttl', 'cmos', 'biên nhiễu', 'họ logic', 'công suất tĩnh', 'nguồn cấp'],
  src=['Jaeger 5e §6.1–6.2, 7.1', 'EASA M04 SM01 (TTL, CMOS)'], related=['m01-cmos', 'm09-esd-physics'], chk='families')
K('m01-cmos', M, ('Bộ đảo CMOS: đặc tuyến, ngưỡng, trễ và công suất', 'The CMOS inverter: transfer curve, threshold, delay and power'),
  ('Một NMOS kéo xuống và một PMOS kéo lên. Ngõ ra đi hết rail (VOH = VDD, VOL = 0), công suất tĩnh ≈ 0; công suất động tỉ lệ C·V²·f.', 'An NMOS pulls down and a PMOS pulls up. The output swings the whole rail (VOH = VDD, VOL = 0) with ≈ 0 static power; dynamic power scales as C·V²·f.'),
  facts=[('VSP = (VDD + VTP + VTN·√KR)/(1 + √KR) ,  KR = Kn/Kp', ('Ngưỡng chuyển mạch; KR = 1 và VTN = −VTP cho VDD/2.', 'Switching threshold; KR = 1 and VTN = −VTP give VDD/2.')), ('P = C·V²·f ,  PDP = P·τp ,  τp = (tPHL + tPLH)/2', ('Công suất động và tích công suất–trễ.', 'Dynamic power and the power–delay product.'))],
  steps=[('Xác định miền làm việc của hai transistor (cắt, tuyến tính, bão hoà) theo vIN.', 'Find each transistor\'s region (cutoff, triode, saturation) for the given vIN.'), ('Với ngưỡng chuyển mạch: cho hai dòng bão hoà bằng nhau rồi giải vIN.', 'For the switching threshold: equate the two saturation currents and solve for vIN.'), ('Công suất động: tính C·V²·f, đổi đơn vị trước khi nhân.', 'Dynamic power: compute C·V²·f, converting units before multiplying.')],
  traps=[('Cho rằng bộ đảo CMOS tiêu thụ công suất tĩnh lớn.', 'Assuming a CMOS inverter draws large static power.'), ('Dùng VDD/2 cho ngưỡng khi KR ≠ 1 hoặc VT không đối xứng.', 'Using VDD/2 for the threshold when KR ≠ 1 or the VT are not symmetric.')],
  angles=[('Tính ngưỡng chuyển mạch VSP cho KR và VT cho trước.', 'Compute the switching threshold VSP for given KR and VT.'), ('Công suất động ở tần số f với tải C và nguồn VDD.', 'Dynamic power at frequency f with load C and supply VDD.')],
  topics=['ICs, TTL and CMOS'], kw=['cmos inverter', 'switching threshold', 'vtc', 'transfer characteristic', 'nmos', 'pmos', 'propagation delay', 'power-delay product', 'dynamic power', 'vsp', 'mosfet'], kwv=['bộ đảo cmos', 'ngưỡng chuyển mạch', 'đặc tuyến truyền đạt', 'trễ truyền', 'công suất động', 'tích công suất trễ'],
  src=['Jaeger 5e §6.11, 7.1–7.5'], related=['m01-families'], chk='cmos')
K('m01-fabrication', M, ('Chế tạo vi mạch', 'How ICs are made'),
  ('Vi mạch được chế tạo trên wafer bán dẫn mỏng; các lớp mạch được khắc bằng quang khắc và các bước hoá học, rồi cắt thành chip và kiểm tra.', 'ICs are made on thin semiconductor wafers; the circuit layers are patterned by photolithography and chemical steps, then cut into chips and tested.'),
  facts=[], steps=[('Wafer → đánh bóng, làm sạch → quang khắc và khắc → kiểm tra → cắt chip.', 'Wafer → polish and clean → photolithography and etching → test → dice into chips.')],
  traps=[('Nghĩ tăng số transistor chỉ làm tăng tốc độ: công suất và nhiệt cũng tăng.', 'Believing more transistors only raise speed: power and heat rise too.')],
  angles=[('Mô tả các bước chính khi chế tạo vi mạch.', 'Describe the main steps in making an IC.')],
  topics=['ICs, TTL and CMOS'], kw=['wafer', 'photolithography', 'etching', 'fabrication', 'die', 'chip', 'integrated circuit', 'transistor count'], kwv=['wafer', 'quang khắc', 'chế tạo', 'vi mạch', 'chip', 'khắc'],
  src=['EASA M04 SM01 (IC manufacture)'], related=['m01-families'])
K('m01-opamp-logic', M, ('Op-amp làm cầu nối giữa tương tự và logic', 'Op-amps as the bridge between analog and logic'),
  ('Op-amp không có hồi tiếp là bộ so sánh (ngõ ra bão hoà ở mức nguồn); có hồi tiếp thì thành mạch lặp áp hoặc tích phân/vi phân. Học kỹ ở module 02 và 03.', 'An op-amp without feedback is a comparator (the output saturates at the supply); with feedback it is a follower or an integrator/differentiator. Studied properly in modules 02 and 03.'),
  facts=[('Vout bão hoà = ±(nguồn) khi |V₊ − V₋| đủ lớn', ('Dấu của V₊ − V₋ quyết định mức ra.', 'The sign of V₊ − V₋ decides the output level.'))],
  steps=[('So V₊ với V₋: V₊ > V₋ → ngõ ra cao; ngược lại → thấp.', 'Compare V₊ with V₋: V₊ > V₋ → output HIGH; otherwise LOW.')],
  traps=[('Quên rằng không có hồi tiếp thì ngõ ra không tuyến tính.', 'Forgetting that without feedback the output is not linear.')],
  angles=[('Ngõ ra của op-amp không hồi tiếp khi V₊ > V₋?', 'What is the output of an open-loop op-amp when V₊ > V₋?')],
  topics=['Op-amp circuits in the logic context'], kw=['comparator', 'saturate', 'open loop', 'voltage follower', 'integrator', 'differentiator', 'op-amp'], kwv=['so sánh', 'bão hoà', 'vòng hở', 'lặp áp', 'tích phân', 'vi phân'],
  src=['EASA M04 SM01 Q1-35…1-38'], related=['m03-comparator', 'm02-ideal-practical'], chk='opampsat')
